// Public studio site (generated by Pylerium Manager): filters, app dialogs, YouTube players, Shorts, sharing and supporter submissions.
// Cards and pages are pre-rendered by the hub's builder; this script only adds interaction.
import { detailHTML, icon, esc, setCategories, categories } from './render.js?v=7af23e5687';

const D = JSON.parse(document.getElementById('site-data').textContent);
const fmtMoney = v => { try { return new Intl.NumberFormat('en', { style: 'currency', currency: D.community?.currency || 'USD', currencyDisplay: 'symbol', minimumFractionDigits: v % 1 ? 2 : 0 }).format(v); } catch { return String(v); } };
setCategories(D.categories);
const BASE = window.SITE_BASE || '';
const MEDIA = BASE + 'assets/apps/';
const HOME = document.body.classList.contains('home');
const byId = new Map(D.apps.map(a => [a.id, a]));
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const appUrl = id => `${(D.siteUrl || location.origin).replace(/\/$/, '')}/apps/${encodeURIComponent(id)}/`;

function toast(msg, ms = 2600) {
  const t = $('#toast'); t.innerHTML = msg; t.classList.add('show');
  clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove('show'), ms);
}

// ---------- announcement ----------
const ann = $('.announce');
if (ann && localStorage.getItem(ann.dataset.key) !== '1') ann.hidden = false;
ann?.querySelector('.ann-x').addEventListener('click', () => { ann.hidden = true; localStorage.setItem(ann.dataset.key, '1'); });

// ---------- nav ----------
const nav = $('.nav');
const cafe = $('.cafe-float');
if (cafe) { let lastY = 0; const upd = () => { const y = scrollY; cafe.classList.toggle('in', y > 420 || !$('.hero')); cafe.classList.toggle('mini', y > 900 && y > lastY); lastY = y; }; addEventListener('scroll', upd, { passive: true }); upd(); }
addEventListener('scroll', () => nav.classList.toggle('scrolled', scrollY > 8), { passive: true });
$('.menu-btn')?.addEventListener('click', () => nav.classList.toggle('open'));
$$('.nav-links a').forEach(a => a.addEventListener('click', () => nav.classList.remove('open')));

// ---------- filters + search (home) ----------
let cat = 'all', q = '';
const cards = $$('#all-apps .pcard');
function apply() {
  let shown = 0;
  for (const c of cards) {
    const a = byId.get(c.dataset.id);
    const hay = [a.name, a.tagline, a.description, a.platform, a.author?.name, ...(a.techStack || []), ...(a.features || [])].join(' ').toLowerCase();
    const ok = (cat === 'all' || (cat === '@community' ? a.community : a.category === cat)) && (!q || hay.includes(q));
    c.classList.toggle('hide', !ok);
    if (ok) shown++;
  }
  $('#empty')?.classList.toggle('show', !shown);
}
function setCat(c) { cat = c; $$('.tab').forEach(x => x.classList.toggle('on', x.dataset.cat === c)); apply(); }
$$('.tab').forEach(t => t.addEventListener('click', () => setCat(t.dataset.cat)));
$('#q')?.addEventListener('input', e => { q = e.target.value.trim().toLowerCase(); apply(); });
$('#clear')?.addEventListener('click', () => { q = ''; $('#q').value = ''; setCat('all'); });
$$('[data-cat-jump]').forEach(b => b.addEventListener('click', () => { setCat(b.dataset.catJump); $('#apps').scrollIntoView({ behavior: 'smooth' }); }));

// ---------- YouTube lite players ----------
function playYT(btn) {
  const id = btn.dataset.yt;
  btn.innerHTML = `<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1&rel=0&modestbranding=1&playsinline=1" title="YouTube video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`;
  btn.removeAttribute('data-yt');
}
const shortDlg = $('#shortDlg');
function openShort(id) {
  $('#shortStage').innerHTML = `<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1&rel=0&playsinline=1&loop=1" title="YouTube Short" allow="autoplay; encrypted-media; picture-in-picture; web-share" allowfullscreen></iframe>`;
  shortDlg.showModal();
}
shortDlg.addEventListener('close', () => ($('#shortStage').innerHTML = ''));
$$('[data-rail]').forEach(b => b.addEventListener('click', () => { const r = $('#shorts'); r.scrollBy({ left: +b.dataset.rail * r.clientWidth * 0.8, behavior: 'smooth' }); }));

// ---------- app dialog (home) ----------
const dlg = $('#dlg'), body = $('#dlg-body');
const BASE_TITLE = document.title;
let lastFocus = null;
function openApp(id, push) {
  const a = byId.get(id);
  if (!a) return false;
  lastFocus = document.activeElement;
  body.innerHTML = detailHTML(a, { mediaBase: MEDIA, base: BASE });
  body.scrollTop = 0;
  document.title = `${a.name} · ${BASE_TITLE.split(' · ')[0]}`;
  if (!dlg.open) dlg.showModal();
  if (push && location.hash !== '#app/' + id) history.pushState(null, '', '#app/' + encodeURIComponent(id));
  return true;
}
function closeApp(fromHash) {
  if (dlg.open) dlg.close();
  document.title = BASE_TITLE;
  if (!fromHash && location.hash.startsWith('#app/')) history.pushState(null, '', location.pathname + location.search);
  lastFocus?.focus?.({ preventScroll: true });
}
$('.dlg-close', dlg).addEventListener('click', () => closeApp());
dlg.addEventListener('click', e => { if (e.target === dlg) closeApp(); });
dlg.addEventListener('cancel', e => { e.preventDefault(); closeApp(); });
for (const d of [shortDlg, $('#submitDlg')]) {
  d.addEventListener('click', e => { if (e.target === d || e.target.closest('.dlg-close')) d.close(); });
}

// ---------- global clicks ----------
document.addEventListener('click', async e => {
  const t = e.target;
  const appLink = t.closest('a[data-app]');
  if (appLink && HOME && !e.ctrlKey && !e.metaKey && !e.shiftKey && e.button === 0) { if (openApp(appLink.dataset.app, true)) e.preventDefault(); return; }
  const hashLink = t.closest('a[href^="#app/"]');
  if (hashLink) { e.preventDefault(); openApp(decodeURIComponent(hashLink.getAttribute('href').slice(5)), true); return; }
  const yt = t.closest('.yt-lite[data-yt]');
  if (yt) { e.preventDefault(); playYT(yt); return; }
  const sh = t.closest('[data-short]');
  if (sh) { openShort(sh.dataset.short); return; }
  const th = t.closest('.d-thumbs button');
  if (th) { const box = th.closest('.detail'); $$('.d-thumbs button', box).forEach(b => b.classList.toggle('on', b === th)); $('.d-stage img', box).src = th.dataset.src; return; }
  const cp = t.closest('.copy');
  if (cp) { try { await navigator.clipboard.writeText(cp.dataset.copy); cp.innerHTML = icon('check') + '<span>Copied</span>'; setTimeout(() => (cp.innerHTML = icon('copy') + '<span>Copy</span>'), 1600); } catch {} return; }
  const share = t.closest('[data-share]');
  if (share) {
    const a = byId.get(share.dataset.share), url = appUrl(share.dataset.share);
    try { if (navigator.share) await navigator.share({ title: a.name, text: a.tagline, url }); else { await navigator.clipboard.writeText(url); toast(`${icon('check')} Link copied`); } } catch {}
    return;
  }
  if (t.closest('[data-submit]')) { e.preventDefault(); openSubmit(); }
});

function route() {
  const m = location.hash.match(/^#app\/(.+)$/);
  if (m && HOME) openApp(decodeURIComponent(m[1]), false);
  else if (dlg.open) closeApp(true);
  if (location.hash === '#thanks') thanks();
  if (location.hash === '#submit') openSubmit();
}
addEventListener('popstate', route);

function thanks() {
  toast(`${icon('can')} <b>Thank you for the caffeine!</b>&nbsp;If you gave ${esc(fmtMoney(+(D.community?.threshold ?? 10)))} or more, your supporter code arrives by email.`, 7000);
  history.replaceState(null, '', location.pathname);
}

// ---------- supporter submissions ----------
const sub = $('#submitDlg'), subBody = $('#submitBody');
const CODE_KEY = location.host + location.pathname.split('/')[1] + '.supporterCode';
const norm = c => String(c || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
async function sha(s) { const b = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s)); return [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join(''); }
const codeHash = code => sha(`${D.community.salt}:${norm(code)}`);
async function validCode(code) { return !!code && D.community.codes.includes(await codeHash(code)); }

async function openSubmit() {
  if (!D.community) return;
  if (!sub.open) sub.showModal();
  const saved = localStorage.getItem(CODE_KEY);
  if (saved && (await validCode(saved))) return showForm(saved);
  showUnlock();
}
function showUnlock(err) {
  const c = D.community;
  subBody.innerHTML = `<div class="sub">
    <div class="sub-hero"><span class="comm-ico">${icon('crown')}</span><h2 id="sub-title">Submit your app</h2><p>Submissions are a thank-you for supporters who give ${esc(fmtMoney(+c.threshold))} or more, or own a lifetime licence. Enter the supporter code from your email to unlock the form.</p></div>
    <form class="unlock" id="unlockForm"><label class="fld"><span>Supporter code</span><input name="code" placeholder="${(D.community?.prefix || 'CAFE')}-XXXX-XXXX-XXXX" autocomplete="off" spellcheck="false" required></label>
      ${err ? `<p class="err">${icon('info')}${esc(err)}</p>` : ''}
      <button class="btn primary" type="submit">${icon('unlock')}Unlock</button></form>
    <div class="sub-alt">
      ${D.donate ? `<a class="caffeine lg" href="${esc(D.donate.url)}" target="_blank" rel="noopener"><span class="steam"><i></i><i></i><i></i></span>${icon('can')}<span>${esc(D.donate.label)}</span></a><p>Give A$${esc(c.threshold)}+ and your code arrives by email.</p>` : ''}
      <p>Bought a lifetime licence? Email <a href="mailto:${esc(c.email)}?subject=${encodeURIComponent('Supporter code request')}">${esc(c.email)}</a> from your purchase address and we'll send your code.</p>
    </div></div>`;
  $('#unlockForm').addEventListener('submit', async e => {
    e.preventDefault();
    const code = e.target.code.value;
    if (await validCode(code)) { localStorage.setItem(CODE_KEY, norm(code)); showForm(norm(code)); }
    else showUnlock("That code didn't match. Check for typos, or email us if it still doesn't work.");
  });
  setTimeout(() => $('#unlockForm input')?.focus(), 50);
}

let iconData = '';
function showForm(code) {
  iconData = '';
  const cats = categories();
  subBody.innerHTML = `<form class="sub" id="subForm" novalidate>
    <div class="sub-hero"><span class="comm-ico ok">${icon('unlock')}</span><h2 id="sub-title">Submit your app</h2><p>Unlocked. Thank you for supporting the studio! Tell us about your app, mod or tool. We review every submission, and accepted ones get their own card with your name.</p></div>
    <div class="sub-grid">
      <div class="icon-pick"><label class="ip" id="ipDrop"><input type="file" accept="image/*" id="ipFile" hidden><span class="ip-img" id="ipImg">${icon('image')}</span><span>App icon</span><small>Square, resized to 128×128</small></label></div>
      <div class="sub-fields">
        <label class="fld"><span>App name *</span><input name="name" maxlength="50" required></label>
        <label class="fld"><span>One-line tagline *</span><input name="tagline" maxlength="110" required></label>
      </div>
    </div>
    <label class="fld"><span>Description <small>Markdown works: **bold**, lists, links</small></span><textarea name="description" rows="4" maxlength="900" placeholder="What it does and who it's for"></textarea></label>
    <div class="f2">
      <label class="fld"><span>Category *</span><select name="category">${cats.map(c => `<option value="${esc(c.id)}">${esc(c.label)}</option>`).join('')}</select></label>
      <label class="fld"><span>Platform</span><input name="platform" maxlength="60" placeholder="e.g. Windows, GTA V, Chrome"></label>
    </div>
    <label class="fld"><span>Download or release page *</span><input name="url" type="url" required placeholder="https://"></label>
    <div class="f2">
      <label class="fld"><span>Source code</span><input name="repoUrl" type="url" placeholder="https://github.com/…"></label>
      <label class="fld"><span>Video (YouTube)</span><input name="videoUrl" type="url" placeholder="https://youtu.be/…"></label>
    </div>
    <label class="fld"><span>Screenshot links <small>(one per line, public image URLs)</small></span><textarea name="screenshots" rows="2" placeholder="https://…/screenshot.png"></textarea></label>
    <div class="f2">
      <label class="fld"><span>Your name or handle *</span><input name="author" maxlength="40" required></label>
      <label class="fld"><span>Your link</span><input name="authorUrl" type="url" placeholder="Channel, GitHub or site"></label>
    </div>
    <label class="check"><input type="checkbox" name="agree" required><span>I made this, or I have the right to share it, and it's free of malware.</span></label>
    <p class="err" id="subErr" hidden></p>
    <div class="sub-actions">
      <button class="btn primary" type="submit" value="github">${icon('github')}Submit via GitHub</button>
      <button class="btn ghost" type="submit" value="email">${icon('mail')}Submit by email</button>
      <button class="linkbtn" type="button" id="forget">Use a different code</button>
    </div>
    <small class="fine">GitHub submissions are public issues, so don't include private details. Email stays private.</small>
  </form>`;
  const f = $('#subForm');
  $('#forget').addEventListener('click', () => { localStorage.removeItem(CODE_KEY); showUnlock(); });
  const pick = async file => {
    if (!file?.type.startsWith('image/')) return;
    iconData = await resizeIcon(file);
    $('#ipImg').innerHTML = `<img src="${iconData}" alt="">`;
  };
  $('#ipFile').addEventListener('change', e => pick(e.target.files[0]));
  const drop = $('#ipDrop');
  drop.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('over'); });
  drop.addEventListener('dragleave', () => drop.classList.remove('over'));
  drop.addEventListener('drop', e => { e.preventDefault(); drop.classList.remove('over'); pick(e.dataTransfer.files[0]); });
  f.addEventListener('submit', async e => {
    e.preventDefault();
    const via = e.submitter?.value || 'github';
    const v = Object.fromEntries(new FormData(f));
    const err = $('#subErr');
    const bad = !v.name.trim() ? 'Add the app name.' : !v.tagline.trim() ? 'Add a tagline.' : !/^https?:\/\//.test(v.url) ? 'Add a download or release link (https://…).' : !v.author.trim() ? 'Add your name or handle.' : !v.agree ? 'Please confirm you can share this app.' : '';
    if (bad) { err.innerHTML = icon('info') + esc(bad); err.hidden = false; return; }
    err.hidden = true;
    const submittedAt = new Date().toISOString();
    const payload = {
      v: 1, name: v.name.trim(), tagline: v.tagline.trim(), description: v.description.trim(), category: v.category, platform: v.platform.trim(),
      url: v.url.trim(), repoUrl: v.repoUrl.trim(), videoUrl: v.videoUrl.trim(),
      screenshots: v.screenshots.split(/\s+/).filter(s => /^https?:\/\//.test(s)).slice(0, 8),
      author: { name: v.author.trim(), url: v.authorUrl.trim() }, submittedAt,
      // Proves the sender knows a valid supporter code without revealing it.
      proof: await sha(`proof:${code}:${v.name.trim()}:${submittedAt}`)
    };
    if (via === 'github') await sendGithub(payload); else sendEmail(payload);
  });
}

async function resizeIcon(file) {
  const img = await createImageBitmap(file);
  const s = 128, c = Object.assign(document.createElement('canvas'), { width: s, height: s }), x = c.getContext('2d');
  const k = Math.max(s / img.width, s / img.height), w = img.width * k, h = img.height * k;
  x.drawImage(img, (s - w) / 2, (s - h) / 2, w, h);
  let out = c.toDataURL('image/webp', 0.82);
  if (!out.startsWith('data:image/webp')) out = c.toDataURL('image/png');
  return out;
}

function issueBody(p, withIcon) {
  const lines = [
    `**${p.name}**: ${p.tagline}`, '', p.description || '', '',
    `- Category: ${(categories().find(c => c.id === p.category) || {}).label || p.category}`,
    p.platform && `- Platform: ${p.platform}`, `- Download: ${p.url}`, p.repoUrl && `- Source: ${p.repoUrl}`, p.videoUrl && `- Video: ${p.videoUrl}`,
    `- By: ${p.author.name}${p.author.url ? ` (${p.author.url})` : ''}`, '',
    p.screenshots.length ? p.screenshots.map(s => `![screenshot](${s})`).join('\n') : '', '',
    '<!-- pylerium-submission -->', '<details><summary>Submission data (please don\'t edit)</summary>', '', '```json',
    JSON.stringify(withIcon && iconData ? { ...p, icon: iconData } : p), '```', '</details>'
  ];
  return lines.filter(l => l !== false && l !== undefined).join('\n');
}
async function sendGithub(p) {
  const title = `[Submission] ${p.name}`;
  const base = `https://github.com/${D.community.repo}/issues/new?title=${encodeURIComponent(title)}`;
  let bodyText = issueBody(p, true);
  let url = `${base}&body=${encodeURIComponent(bodyText)}`;
  let copied = false;
  if (url.length > 7800) { // too long for a link (usually the icon): copy it instead
    try { await navigator.clipboard.writeText(bodyText); copied = true; } catch {}
    url = copied ? `${base}&body=${encodeURIComponent('(Paste your submission here with Ctrl+V)')}` : `${base}&body=${encodeURIComponent(issueBody(p, false))}`;
  }
  window.open(url, '_blank', 'noopener');
  done(copied
    ? 'GitHub opened in a new tab. Your submission is on the clipboard: <b>paste it into the description</b> (Ctrl+V), then press <b>Create</b>.'
    : 'GitHub opened in a new tab with your submission filled in. Press <b>Create</b> to send it. (You need a free GitHub account.)');
}
function sendEmail(p) {
  const text = issueBody(p, false) + (iconData ? '\n\n(Please attach your app icon to this email.)' : '');
  location.href = `mailto:${D.community.email}?subject=${encodeURIComponent(`[Submission] ${p.name}`)}&body=${encodeURIComponent(text)}`;
  done('Your email app opened with the submission filled in. Attach your icon and screenshots, then send it.');
}
function done(msg) {
  subBody.innerHTML = `<div class="sub done"><span class="comm-ico ok big">${icon('check')}</span><h2 id="sub-title">Almost there</h2><p>${msg}</p><p class="fine">We review every submission and reply within a week. Accepted apps appear in the Community section with your name.</p><button class="btn ghost" type="button" onclick="this.closest('dialog').close()">Close</button></div>`;
}

// ---------- featured spotlight ----------
const spot = $('#spot');
if (spot && $$('.spot-slide', spot).length > 1) {
  const track = $('.spot-track', spot), dots = $$('.spot-dots button', spot), n = dots.length, MS = 7000;
  let idx = 0, timer = 0, paused = false;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const go = i => { idx = (i + n) % n; track.scrollTo({ left: idx * (track.clientWidth + 22), behavior: 'smooth' }); mark(); };
  const mark = () => { dots.forEach((d, j) => d.classList.toggle('on', j === idx)); restart(); };
  const restart = () => {
    clearTimeout(timer); spot.classList.remove('playing'); void spot.offsetWidth;
    if (paused || reduce) return;
    spot.style.setProperty('--spot-ms', MS + 'ms'); spot.classList.add('playing');
    timer = setTimeout(() => go(idx + 1), MS);
  };
  $$('[data-spot]', spot).forEach(b => b.addEventListener('click', () => go(idx + +b.dataset.spot)));
  dots.forEach((d, j) => d.addEventListener('click', () => go(j)));
  let st = 0;
  track.addEventListener('scroll', () => { clearTimeout(st); st = setTimeout(() => { const j = Math.round(track.scrollLeft / (track.clientWidth + 22)); if (j !== idx) { idx = j; mark(); } }, 120); }, { passive: true });
  spot.addEventListener('mouseenter', () => { paused = true; restart(); });
  spot.addEventListener('mouseleave', () => { paused = false; restart(); });
  spot.addEventListener('focusin', () => { paused = true; restart(); });
  spot.addEventListener('focusout', () => { paused = false; restart(); });
  document.addEventListener('visibilitychange', () => { paused = document.hidden; restart(); });
  new IntersectionObserver(([e]) => { paused = !e.isIntersecting; restart(); }).observe(spot);
  addEventListener('resize', () => track.scrollTo({ left: idx * (track.clientWidth + 22) }));
}

route();
